from collections import Counter
from operator import itemgetter
import itertools

def task_func(word_dict):
    if not word_dict:
        return {}

    letters = (
        ch
        for word in word_dict.keys()
        if isinstance(word, str)
        for ch in word
        if ch.isalpha()
    )
    return dict(Counter(letters))
